// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Brick bounce: the ball must NEVER go through a brick -------------------

// Brick grid geometry, derived from the same constants as makeBricks().
const OFFSET_X = (WIDTH - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
const brickX = (col) => OFFSET_X + col * (BRICK_W + BRICK_GAP);
const brickY = (row) => BRICK_TOP + row * (BRICK_H + BRICK_GAP);
const brickAt = (state, row, col) =>
  state.bricks.find((b) => b.x === brickX(col) && b.y === brickY(row));

test('bricks: ball hitting a top face flips vy up and leaves the rectangle', () => {
  const state = createState(1);
  const brick = brickAt(state, 0, 3);
  state.ball = { x: brickX(3) + BRICK_W / 2, y: brickY(0) - BALL_R - 1, r: BALL_R, vx: 0, vy: 200 };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'vy must point upward after a top-face hit');
  assert.ok(state.ball.y + BALL_R <= brick.y, 'the ball must end above the brick');
  assert.equal(brick.alive, false, 'the hit brick is destroyed');
  assert.equal(Math.hypot(state.ball.vx, state.ball.vy), 200, 'speed is preserved');
});

test('bricks: ball hitting a bottom face flips vy down and leaves the rectangle', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 3);
  state.ball = { x: brickX(3) + BRICK_W / 2, y: brickY(4) + BRICK_H + BALL_R + 1, r: BALL_R, vx: 0, vy: -200 };
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'vy must point downward after a bottom-face hit');
  assert.ok(state.ball.y - BALL_R >= brick.y + brick.h, 'the ball must end below the brick');
  assert.equal(brick.alive, false, 'the hit brick is destroyed');
  assert.equal(Math.hypot(state.ball.vx, state.ball.vy), 200, 'speed is preserved');
});

test('bricks: ball hitting a side face flips vx away and leaves the rectangle', () => {
  const state = createState(1);
  brickAt(state, 2, 1).alive = false; // a hole next to the target, as in a real game
  const brick = brickAt(state, 2, 2);
  state.ball = { x: brick.x - BALL_R, y: brick.y + BRICK_H / 2, r: BALL_R, vx: 200, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx must point away from the brick');
  assert.ok(state.ball.x + BALL_R <= brick.x, 'the ball must end left of the brick');
  assert.equal(brick.alive, false, 'the hit brick is destroyed');
  assert.equal(Math.hypot(state.ball.vx, state.ball.vy), 200, 'speed is preserved');
});

test('bricks: axis of smallest penetration wins — a shallow top overlap flips vy only', () => {
  const state = createState(1);
  const brick = brickAt(state, 1, 2);
  // Deep x overlap (38 px), shallow y overlap (10 px): the hit is the top face.
  state.ball = { x: brick.x + 40, y: brick.y + 2, r: BALL_R, vx: 60, vy: 60 };
  step(state, 1 / 60);
  assert.equal(state.ball.vx, 60, 'vx untouched on a top-face hit');
  assert.ok(state.ball.vy < 0, 'vy flipped up');
  assert.ok(state.ball.y + BALL_R <= brick.y, 'ball pushed out above the brick');
});

test('bricks: corner hit — equal penetration on both axes flips both components', () => {
  const state = createState(1);
  const brick = brickAt(state, 1, 2);
  // Ball centre 2 px inside the top-left corner: 10 px penetration on each axis.
  state.ball = { x: brick.x + 2, y: brick.y + 2, r: BALL_R, vx: 60, vy: 60 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both components flip on a corner');
  assert.ok(
    state.ball.x + BALL_R <= brick.x && state.ball.y + BALL_R <= brick.y,
    'ball pushed out of the brick diagonally'
  );
});

test('bricks: no tunneling — a step longer than the brick depth still bounces (level 6, dt = 50 ms)', () => {
  const speed = ballSpeed(6);
  assert.ok(
    speed * 0.05 > BRICK_H + 2 * BALL_R,
    'precondition: this step CAN cross a brick in a single frame'
  );
  const state = createState(6);
  const brick = brickAt(state, 0, 3);
  state.ball = { x: brickX(3) + BRICK_W / 2, y: brickY(0) - BALL_R - 1, r: BALL_R, vx: 0, vy: speed };
  step(state, 0.05); // the raw step ends below the brick: an overlap test alone would miss it
  assert.ok(state.ball.vy < 0, 'the ball bounces instead of passing through');
  assert.ok(state.ball.y + BALL_R <= brick.y, 'the ball ends above the brick');
  assert.equal(brick.alive, false, 'the hit brick is destroyed');
  assert.equal(Math.hypot(state.ball.vx, state.ball.vy), speed, 'speed preserved');
});

test('bricks: seam straddle — exactly one flip per pass, no double inversion', () => {
  const state = createState(1);
  const left = brickAt(state, 0, 3);
  const right = brickAt(state, 0, 4);
  // Ball diameter (2·BALL_R = 14) is wider than the gap between bricks (8).
  state.ball = { x: left.x + BRICK_W + BRICK_GAP / 2, y: BRICK_TOP - BALL_R - 1, r: BALL_R, vx: 0, vy: 260 };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'exactly one vy flip: two would cancel and the ball would go through');
  assert.ok(state.ball.y + BALL_R <= BRICK_TOP, 'the ball ends above the seam');
  assert.equal(left.alive, false, 'the first brick of the seam is destroyed');
  assert.equal(right.alive, true, 'the second brick of the seam is untouched');
});

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

