  // Bricks: sweep the segment travelled this step and bounce off the earliest
  // contact (see resolveBricks). Runs after the walls so the paddle and the
  // side walls keep their exact previous behaviour.
  resolveBricks(state, prevX, prevY);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

